{"implementation": "def solve(case):
    nodes = case["nodes"]
    required_symbols = set(case["required_symbols"])

    # Validate structure
    if not isinstance(nodes, list) or len(nodes) == 0:
        raise ValueError("nodes must be a non-empty list")
    if not isinstance(case["required_symbols"], list):
        raise ValueError("required_symbols must be a list")

    node_map = {}
    for node in nodes:
        nid = node["id"]
        if nid in node_map:
            raise ValueError(f"Duplicate node id: {nid}")
        node_map[nid] = node

    # Build children map
    children = {nid: [] for nid in node_map}
    for node in nodes:
        parent = node["parent"]
        if parent is not None:
            if parent not in node_map:
                raise ValueError(f"Parent {parent!r} not found for node {node['id']!r}")
            children[parent].append(node["id"])

    # Verify all required symbols are present in at least one node
    symbols_present = {node["symbol"] for node in nodes}
    for sym in required_symbols:
        if sym not in symbols_present:
            raise ValueError(f"Required symbol {sym!r} not present in any node")

    # Build symbol -> set of node IDs
    symbol_nodes = {}
    for node in nodes:
        sym = node["symbol"]
        symbol_nodes.setdefault(sym, set()).add(node["id"])

    # retained status
    retained = {node["id"]: True for node in nodes}

    # Process order: deeper nodes first, tie-break by node ID (lexicographic)
    sorted_nodes = sorted(nodes, key=lambda n: (-n["depth"], n["id"]))

    removed_order = []

    for node in sorted_nodes:
        nid = node["id"]

        # Must be removable
        if not node["removable"]:
            continue

        # Must not have any retained children
        if any(retained[c] for c in children[nid]):
            continue

        # Check required symbol coverage: only this node's symbol could be affected
        sym = node["symbol"]
        if sym in required_symbols:
            # Count other retained nodes with this symbol
            other_retained = sum(
                1 for nid2 in symbol_nodes.get(sym, set())
                if nid2 != nid and retained[nid2]
            )
            if other_retained == 0:
                # Removing this would eliminate a required symbol
                continue

        # Remove the node
        retained[nid] = False
        removed_order.append(nid)

    retained_node_ids = sorted(nid for nid, r in retained.items() if r)

    return {
        "removed_node_ids": removed_order,
        "retained_node_ids": retained_node_ids
    }
"}
